106	\midrule
107	Qwen3-1.7B & 47.86 & 39.82 & 51.22 & +8.04 & +3.36 \\
108	Qwen3-4B & 39.74 & 47.21 & 44.66 & $-$7.47 & +4.92 \\
109	Qwen3-8B & 50.51 & 50.79 & \textbf{54.24} & $-$0.28 & +3.73 \\
110	LLaMA-3.1-8B & 53.84 & 54.52 & 57.14 & $-$0.68 & +3.30 \\
111	\bottomrule
112	\end{tabular}%
113	}
114	\end{table}
